// Uses existing disposable history; no generation, Apply, settings, or catalog writes.
const {chromium}=require('/Users/user/dreamlayer_browser/node_modules/playwright');
const fs=require('node:fs'),assert=require('node:assert/strict');
const base='http://127.0.0.1:8190',out=require('node:path').resolve(__dirname,'../../qa/compact-cards-20261023');fs.mkdirSync(out,{recursive:true});
let browser,page;const checks=[],errors=[];
(async()=>{
 browser=await chromium.launch({headless:true});const context=await browser.newContext({viewport:{width:1440,height:1000}});page=await context.newPage();page.setDefaultTimeout(180000);page.setDefaultNavigationTimeout(180000);page.on('pageerror',e=>errors.push(e.message));
 await page.goto(base+'/admin/login');await page.locator('[name=email]').fill('marketplace-test@example.test');await page.locator('[name=password]').fill('Local-Test-2026');await page.getByRole('button',{name:'Sign In',exact:true}).click();await page.waitForURL('**/dashboard');
 const threads=await(await context.request.get(base+'/admin/dreamlayer/studio/threads')).json();let thread,saved;
 for(const item of threads.items){const data=await(await context.request.get(base+'/admin/dreamlayer/studio/threads/'+item.id)).json();if(data.turns.flatMap(t=>t.workflow_ids).length>=2){thread=item;saved=data;break;}}assert(thread,'Seeded batch history required');
 let editingOff=false,phase='real';const ids=saved.turns.flatMap(t=>t.workflow_ids);let original;
 await context.route('**/admin/dreamlayer/studio/config',async route=>{const response=await route.fetch(),data=await response.json();if(editingOff)data.connected=false;await route.fulfill({response,json:data});});
 await context.route('**/admin/dreamlayer/workflows/*',async route=>{assert.equal(route.request().method(),'GET');if(phase!=='real'&&route.request().url().endsWith('/'+ids[0])){await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({status:phase,error:phase==='failed'?'Test provider failure':null})});return;}const response=await route.fetch().catch(()=>null);if(!response)return;if(route.request().url().endsWith('/'+ids[0])){const data=await response.json();original=data;await route.fulfill({response,json:phase==='real'?data:{status:phase,error:phase==='failed'?'Test provider failure':null}});}else await route.fulfill({response});});
 const open=async()=>{await page.goto(base+'/admin/dreamlayer/choose');const f=page.frameLocator('#dreamlayer-shell iframe');await f.getByRole('button',{name:'History',exact:true}).click();await f.locator('.thread-open').filter({hasText:thread.title}).first().click();return f;};
 let f=await open();await f.locator('.result-image').nth(ids.length-1).waitFor();const card=f.locator('.result').first();await card.locator('.result-image').evaluate(n=>n.decode());
 assert.equal(await f.getByRole('button',{name:/^(Copy|Helpful|Not helpful)$/}).count(),0);assert.equal(await f.locator('.result-status').count(),0);assert(!/default \/ en_US/.test(await card.innerText()));
 const note=await card.locator('.catalog-notice').innerText();assert.match(note,/Nothing changes in your catalog until you choose Apply to product\./);assert(!/fitted to|MB limit/.test(note));assert.equal(await card.getByText('Nothing changes in your catalog until you choose Apply to product.',{exact:true}).count(),0,'Reminder shares preview paragraph');
 assert(await card.getByRole('button',{name:'Apply to product',exact:true}).isEnabled());await card.getByRole('button',{name:'View full image'}).click();await f.locator('#image-dialog').waitFor();await f.locator('#image-dialog').getByRole('button',{name:'Close',exact:true}).click();checks.push('Compact real saved batch: no Complete, Copy, feedback, channel/locale or size-limit clause; one combined preview reminder; image viewer retained');
 for(const[width,dark]of[[1440,false],[1440,true],[390,true]]){await page.setViewportSize({width,height:1000});await page.evaluate(d=>document.documentElement.classList.toggle('dark',d),dark);await page.waitForTimeout(200);assert(await f.locator('body').evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await card.scrollIntoViewIfNeeded();await page.screenshot({path:out+'/cards-'+width+'-'+dark+'.png'});}
 editingOff=true;await page.waitForResponse(r=>r.url().endsWith('/studio/config'),{timeout:20000});await page.waitForTimeout(100);assert(await card.getByRole('button',{name:'Apply to product',exact:true}).isDisabled());assert(await card.getByRole('button',{name:'Refine this image',exact:true}).isDisabled());checks.push('Simulated config refresh disables both Apply and Refine while leaving history readable');
 editingOff=false;phase='running';await context.clearCookies();await page.close(); // Fresh session avoids cached completed data.
 page=await context.newPage();page.setDefaultTimeout(180000);page.setDefaultNavigationTimeout(180000);page.on('pageerror',e=>errors.push(e.message));await page.goto(base+'/admin/login');await page.locator('[name=email]').fill('marketplace-test@example.test');await page.locator('[name=password]').fill('Local-Test-2026');await page.getByRole('button',{name:'Sign In',exact:true}).click();await page.waitForURL('**/dashboard');f=await open();await f.getByText('Processing',{exact:true}).waitFor();assert.match(await f.locator('.result-status').first().innerText(),/Processing/);
 phase='failed';await f.getByText('Test provider failure',{exact:true}).waitFor();assert.match(await f.locator('.result-status').first().innerText(),/Failed/);checks.push('Simulated running and failed workflow responses retain visible status and error');
 assert.deepEqual(errors,[]);fs.writeFileSync(out+'/results.json',JSON.stringify({checks,errors,workflow_ids:ids,mode:'Real isolated saved history; explicit response simulations for pending/failure and editing-off refresh; no paid requests or catalog writes'},null,2));console.log(JSON.stringify({checks,errors}));
})().catch(async e=>{console.error(e.name+': '+e.message.split('Call log:')[0]);await page?.screenshot({path:out+'/failure.png'}).catch(()=>{});process.exitCode=1;}).finally(async()=>browser?.close());
